import manifest from '@/data/image-manifest.json'

/** Generated by `npm run images` — see scripts/optimize-images.js. */
export type ImageName = keyof typeof manifest

export type ImageFormat = 'avif' | 'webp'

export function getImage(name: ImageName) {
  return manifest[name]
}

export function imageUrl(name: ImageName, width: number, format: ImageFormat) {
  return `/images/${name}-${width}.${manifest[name].hash}.${format}`
}

export function imageSrcSet(name: ImageName, format: ImageFormat) {
  return manifest[name].widths.map((w) => `${imageUrl(name, w, format)} ${w}w`).join(', ')
}
